import React, { useState } from 'react';
import { useApiPost } from './useApiPost';
import API_BASE_URL from './config';

const API_URL = `${API_BASE_URL}/generate-test-cases`;

function TestCaseGenerator() {
    const [userStory, setUserStory] = useState('');
    const [copySuccess, setCopySuccess] = useState('');
    const { data: result, error, isLoading, postData } = useApiPost(API_URL);

    const handleGenerate = async () => {
        setCopySuccess(''); // Reset copy message on new generation
        postData({ userStory });
    };

    const handleCopy = () => {
        if (!result || !result.testCases) return;
        const textToCopy = result.testCases.join('\n');
        navigator.clipboard.writeText(textToCopy).then(() => {
            setCopySuccess('Copied!');
            setTimeout(() => setCopySuccess(''), 2000); // Reset message after 2 seconds
        }, () => {
            setCopySuccess('Failed!');
        });
    };

    return (
        <div className="feature-container">
            <h2>3. Test Case Generator</h2>
            <textarea
                value={userStory}
                onChange={(e) => setUserStory(e.target.value)}
                placeholder="Paste a user story or requirement here..."
                disabled={isLoading}
            />
            <button onClick={handleGenerate} disabled={!userStory || isLoading}>
                {isLoading ? 'Generating...' : 'Generate Test Cases'}
            </button>
            {error && <p style={{ color: 'red' }}>{error}</p>}
            {result && (
                <div className="results">
                    <div className="results-header">
                        <h3>Generated Test Cases:</h3>
                        <button className="copy-btn" onClick={handleCopy}>{copySuccess || 'Copy'}</button>
                    </div>
                    <ul>
                        {result.testCases.map((testCase, index) => (
                            <li key={index}>{testCase}</li>
                        ))}
                    </ul>
                </div>
            )}
        </div>
    );
}

export default TestCaseGenerator;
